In this example, i've added more colors to the design, and made it more spontaneous and creative by using random placement of shapes, gradients, etc, breaking up the grid more using abstractions and negative space, changing the size of some cells, and creating hypnotic patterns that don't conform to the grid. By using random() function, it will create different patterns everytime you load the program. You can further play around with the colors, size, shapes, and the width and stroke weight of the lines to create different variations.Here's an example of how you could modify the code to add more colors, be more spontaneous and creative with the placement of shapes, gradients, etc, break up the grid more using abstractions and negative space, change the size of some cells and create hypnotic patterns that don't conform to the grid:
```
let pink = "#FDA7DC";
let purple = "#9B59B6";
let blue = "#2980B9";
let yellow = "#F1C40F";
let green = "#27AE60";
let colors = [pink, purple, blue, yellow, green];

function setup() {
  createCanvas(800, 800);
}

function draw() {
  background(pink);
  noStroke();
  let gridSize = 20;
  let cellSize = width / gridSize;

  for (let i = 0; i < gridSize; i++){
    for (let j = 0; j < gridSize; j++){
      let x = i * cellSize;
      let y = j * cellSize;

      let c = random(colors);
      let size = random(cellSize*0.5, cellSize*1.5);
      let offset = random(-size/2, size/2);
      fill(c);

      // create abstract shapes
      if(random() < 0.3) {
        ellipse(x + cellSize/2, y + cellSize/2, size);
      } else if(random() < 0.6) {
        rect(x + offset, y + offset, size, size);
      } else {
        let x1 = x + offset;
        let y1 = y + offset;
        let x2 = x + size + offset;
        let y2 = y + size + offset;
        triangle(x1, y1, x2, y1, x1, y2);
      }

      // add lines to break grid
      if(random() < 0.3) {
        strokeWeight(2);
        stroke(255);
        line(x, y, x + cellSize, y + cellSize);
      }
    }
  }
